// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EmergencyOracleFactory} from "../src/EmergencyOracleFactory.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EmergencyOracleFactory c;

    function setUp() public {
        c = new EmergencyOracleFactory();
    }

    function _runTest(address jojoTeamAddr, address caller, string memory description) internal {
        vm.assume(caller != address(0));
        bool successDirect;
        try c.newEmergencyOracle(description) {
            successDirect = true;
        } catch {
            successDirect = false;
        }
        assertTrue((address(this) != jojoTeamAddr) ? (successDirect == false) : true);
    }

    function testFuzz_runTest(address jojoTeamAddr, address caller, string memory description) public {
        vm.assume(jojoTeamAddr.code.length == 0 && uint160(jojoTeamAddr) > 0xffff && jojoTeamAddr != address(this) && jojoTeamAddr != address(c) && jojoTeamAddr != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && jojoTeamAddr != 0x000000000000000000636F6e736F6c652e6c6f67 && jojoTeamAddr != 0x4e59b44847b379578588920cA78FbF26c0B4956C && jojoTeamAddr != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(caller.code.length == 0 && uint160(caller) > 0xffff && caller != address(this) && caller != address(c) && caller != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && caller != 0x000000000000000000636F6e736F6c652e6c6f67 && caller != 0x4e59b44847b379578588920cA78FbF26c0B4956C && caller != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _runTest(jojoTeamAddr, caller, description);
    }

    receive() external payable {}
}
